import ast

def is_valid_expression(expr: str) -> bool:
    try:
        tree = ast.parse(expr, mode='eval')
        return isinstance(tree, ast.Expression)
    except SyntaxError:
        return False

# Test cases
print(is_valid_expression("2 + 3 * 5"))  # Expected: True
print(is_valid_expression("2 + (3 * 5"))  # Expected: False
print(is_valid_expression("2 + 'string'"))  # Expected: False
